@misc{nhanes,
  author       = {Mo, Yuanhan and Papie{\.z}, Bart{\l}omiej W. and Chen, Yao and Mandal, Indrajeet and Jabbar, Faiz},
  title        = {{NHANES II} Spinal {X}-ray with Extra Labels For Reference Vertebral Bodies ({C2}, {S1})},
  howpublished = {Zenodo dataset},
  year         = {2023},
  month        = nov,
  doi          = {10.5281/zenodo.10223910},
  url          = {https://zenodo.org/records/10223910},
annote = {Version published 2023-11-30 (concept DOI 10.5281/zenodo.10145564); licence CC BY 4.0. Fifth creator listed on the deposit as ``Faiz, Jabbra''; name as given in the companion article. One archive of 543 pickled files (275 cervical, 268 lumbar) holding per-vertebra masks derived from the original NHANES II landmark annotations, plus C2 and S1 reference-vertebra labels added by two radiologists, for a subset of the NHANES II lateral cervical and lumbar spine radiographs (National Center for Health Statistics, collected 1976--1980; films scanned at UCLA/UCSF in the early 1990s and first distributed by the National Library of Medicine; re-released by NCHS in August 2025 at https://wwwn.cdc.gov/nchs/data/nhanes2/NH2_Xray.htm). Companion article: Chen Y, Mo Y, et al., Sci Rep 2024;14:3341, doi:10.1038/s41598-023-49923-3, PMID 38336974, PMCID PMC10858234. Accessed 2026-09-22}
}

